const taskForm = ref({title:'',description:'',priority:'medium',dueDate:'',state:'planned'}); const docForm = ref({name:'',type:'file',content:''}); const inviteForm = ref({email:'',role:'member'}); const invitations = ref([]); const inviteLink = ref(''); const inviteCode = ref(new URLSearchParams(location.search).get('code') || ''); const inviteInfo = ref(null); const inviteAcceptForm = ref({name:'',email:''}); const inviteAcceptState = ref('idle'); const deviceForm = ref({name:'ziwei_user',token:''}); const employeeForm = ref({name:'',runtime:'Hermes',instructions:''}); const automationForm = ref({name:'',schedule:'每天 09:00',prompt:''});
