const visibleTasks = computed(() => {
  const filtered = tasks.value.filter(task => (issueTab.value === 'all' || task.state === issueTab.value) && (!search.value.trim() || `${task.title} ${task.description}`.toLowerCase().includes(search.value.toLowerCase())) && (!selectedStates.value.length || selectedStates.value.includes(task.state)) && (!selectedPriorities.value.length || selectedPriorities.value.includes(task.priority)));
  return [...filtered].sort((a,b) => issueSort.value === 'title' ? a.title.localeCompare(b.title) : issueSort.value === 'priority' ? ({high:0,medium:1,low:2}[a.priority]??3)-({high:0,medium:1,low:2}[b.priority]??3) : new Date(a.created_at||0)-new Date(b.created_at||0));
});
