async function handleSkillImportFile(event) { const file=event.target.files?.[0]; if (!file) return; skillImportForm.value={...skillImportForm.value,name:file.name.replace(/(?:^|[\\/])SKILL\.md$/i,'').replace(/\.md$/i,''),content:await file.text()}; event.target.value=''; }
async function importSkill() { if (!skillImportForm.value.content.trim()) return notify('请选择或粘贴 SKILL.md 内容'); try { await api.importSkill({name:skillImportForm.value.name || undefined,description:skillImportForm.value.description || undefined,content:skillImportForm.value.content,sourceType:'markdown'}); showSkillImport.value=false; await load(); skillScope.value='team'; notify('SKILL.md 已导入'); } catch (error) { notify(error.message); } }
async function createSkill() { if (!skillForm.value.name.trim()) return notify('请填写技能名称'); await api.createSkill({ ...skillForm.value, scope:'team', tags:skillForm.value.tags.split(/[,，\s]+/).map(item => item.trim()).filter(Boolean) }); showSkillModal.value=false; await load(); skillScope.value='team'; skillTab.value='all'; notify('团队技能已添加'); }
async function loadInvitations() { try { invitations.value=(await api.invitations()).invitations || []; } catch (error) { notify(error.message); } }
async function invite() { if (!inviteForm.value.email.trim()) return notify('请填写成员邮箱'); try { const result=await api.createInvitation(inviteForm.value); inviteLink.value=result.link || ''; await loadInvitations(); await load(); notify(`邀请已创建：${inviteForm.value.email}`); inviteForm.value={email:'',role:'member'}; } catch(error) { notify(error.message); } }
async function createInviteLink() { try { const result=await api.createInvitation({role:'member'}); inviteLink.value=result.link || ''; await loadInvitations(); try { await navigator.clipboard?.writeText(inviteLink.value); } catch {} notify('邀请链接已创建并复制'); } catch(error) { notify(error.message); } }
async function revokeInvite(item) { try { await api.revokeInvitation(item.id); await loadInvitations(); notify('邀请已撤销'); } catch(error) { notify(error.message); } }
async function loadInvite() { if (!inviteCode.value) { inviteAcceptState.value='invalid'; return; } try { inviteInfo.value=await api.lookupInvitation(inviteCode.value); inviteAcceptForm.value.email=inviteInfo.value.email || ''; inviteAcceptState.value='ready'; } catch(error) { inviteAcceptState.value='invalid'; notify(error.message); } }
async function acceptInvite() { if (!inviteAcceptForm.value.email.trim()) return notify('请填写邮箱'); try { await api.acceptInvitation(inviteCode.value, inviteAcceptForm.value); inviteAcceptState.value='accepted'; notify('已加入工作区'); } catch(error) { notify(error.message); } }
async function addDevice() { await api.addDevice(deviceForm.value); closeDeviceModal(); await load(); notify('设备登记已创建，等待 ziwei_user 心跳'); }
function openEmployeeModal() { employeeModalTab.value='manual'; employeeVisibility.value='workspace'; employeeModel.value='default'; employeeModelSearch.value=''; employeeDescription.value=''; employeeRole.value=''; employeeSkillsOpen.value=false; employeeRuntimeOpen.value=false; employeeModelOpen.value=false; employeeSkillIds.value=[]; employeeForm.value={name:'',runtime:runtimes.value.some(r=>r.name==='Hermes')?'Hermes':(runtimes.value[0]?.name || 'Codex'),instructions:''}; showEmployee.value=true; }
function selectEmployeeRuntime(name) { employeeForm.value.runtime=name; employeeRuntimeOpen.value=false; }
function selectEmployeeModel(value) { employeeModel.value=value; employeeModelOpen.value=false; }
function toggleEmployeeSkill(id) { employeeSkillIds.value = employeeSkillIds.value.includes(id) ? employeeSkillIds.value.filter(item => item !== id) : [...employeeSkillIds.value, id]; }
async function addEmployee() { if(!employeeForm.value.name.trim()) return notify('请填写数字员工名称'); await api.createEmployee({...employeeForm.value,model:employeeModel.value === 'default' ? null : employeeModel.value,description:employeeDescription.value,visibility:employeeVisibility.value,skills:employeeSkillIds.value,instructions:employeeRole.value || employeeForm.value.instructions}); showEmployee.value=false; await load(); notify('数字员工草稿已创建'); employeeForm.value={name:'',runtime:'Hermes',instructions:''}; employeeModel.value='default'; employeeModelSearch.value=''; employeeDescription.value=''; employeeRole.value=''; }
window.addEventListener('popstate', () => { page.value=routeFromPath(location.pathname); inviteCode.value=new URLSearchParams(location.search).get('code') || ''; if (page.value==='invite-accept') loadInvite(); });
onMounted(async () => { await load(); if (page.value==='invite') await loadInvitations(); if (page.value==='invite-accept') await loadInvite(); if (page.value==='open') await loadApiKeys(); });
</script>

<template>
  <WorkspaceShell :page="page" :account="{name:'紫薇用户',email:'owner@example.com',role:'owner'}" @navigate="navigate">
    <section class="content">
        <div v-if="toast" class="notice" style="margin-bottom:16px">{{ toast }}</div>
        <div v-if="page==='home'">
          <div class="home-header"><div><span class="eyebrow">紫薇工作区 · test-111</span><h1>今天想让 Agent 帮你做什么？</h1><p>选择一个数字伙伴，开始一段可追踪的工作。</p></div><button class="home-help" @click="openHelp">需要帮助？</button></div>
          <ZiCard class="agent-launcher"><div class="agent-launcher-main"><div class="agent-orb">✦</div><div><strong>选择数字伙伴</strong><p>还没有可用的数字伙伴</p><button class="link-button" @click="navigate('members')">前往团队管理添加设备和 Agent →</button></div></div><ZiButton disabled>开始对话</ZiButton></ZiCard>
          <div class="quick-grid home-quick"><button class="quick" @click="addTaskInLane()"><span class="quick-icon">＋</span><b>新建任务</b><span>把下一步行动交给紫薇</span></button><button class="quick" @click="navigate('issues')"><span class="quick-icon">▤</span><b>汇总项目进展</b><span>查看最近的执行状态</span></button><button class="quick" @click="navigate('calendar')"><span class="quick-icon">◷</span><b>查看近期安排</b><span>浏览任务和自动化日程</span></button></div>
          <div class="home-section-title"><h2>工作区概览</h2><button class="link-button" @click="navigate('settings')">管理工作区 →</button></div>
          <div class="grid-4"><ZiMetricCard label="待处理任务" :value="summary.taskStates.todo || 0" note="需要你的关注" tone="default"/><ZiMetricCard label="在线运行时" :value="summary.counts.runtimes" note="A2A 可调度" tone="positive"/><ZiMetricCard label="项目文档" :value="summary.counts.documents" note="持续沉淀中" tone="default"/><ZiMetricCard label="自动化" :value="summary.counts.automations" note="已配置流程" tone="positive"/></div>
          <div class="grid-2" style="margin-top:16px"><ZiCard><div class="card-heading"><h3>本机连接</h3><ZiStatusTag :status="ownDeviceOnline?'online':'neutral'" :label="ownDeviceLabel" dot/></div><div class="runtime-row"><ZiAvatar name="ziwei_user" size="sm" :status="ownDeviceOnline?'online':'neutral'"/><div class="row-main"><strong>{{ summary.device?.name || 'ziwei_user' }}</strong><small>ziwei_user · {{ summary.device?.bridge_version ? `v${summary.device.bridge_version}` : '等待心跳' }} · {{ summary.device?.bridge_host || '127.0.0.1' }}</small></div><span class="row-end">{{ ownDeviceOnline ? '刚刚' : '—' }}</span></div><ZiProgress :value="ownDeviceOnline ? 100 : 0" label="ziwei_user 心跳健康度" :tone="ownDeviceOnline?'positive':'neutral'"/></ZiCard><ZiCard><div class="card-heading"><h3>运行时</h3><button class="icon-button" @click="navigate('members')">全部 →</button></div><div v-for="runtime in runtimes.slice(0,3)" :key="runtime.id" class="runtime-row"><ZiAvatar :name="runtime.name" size="sm"/><div class="row-main"><strong>{{ runtime.name }}</strong><small>{{ runtime.provider }} · {{ runtime.cli_version || '等待 ziwei_user 心跳' }}</small></div><ZiStatusTag :status="runtime.cli_status==='available'?'online':'neutral'" :label="runtime.cli_status==='available'?'在线':'离线'" dot/></div></ZiCard></div>
        </div>

        <div v-else-if="page==='issues'" class="tasks-page">
          <div class="task-page-header">
            <div class="task-page-title"><ZiIcon name="activity" :size="19"/><h1>任务</h1></div>
            <ZiButton class="automation-button" variant="secondary" @click="showAutomation=true"><Zap :size="16"/>自动化</ZiButton>
          </div>
          <div class="task-board-toolbar">
            <div class="task-scope-tabs">
              <button class="scope-tab" :class="{active:issueTab==='all'}" @click="issueTab='all'">全部</button>
              <button class="scope-tab" :class="{active:issueTab==='todo'}" @click="issueTab='todo'">成员</button>
              <button class="scope-tab" :class="{active:issueTab==='in_progress'}" @click="issueTab='in_progress'">数字伙伴</button>
            </div>
            <div class="task-toolbar-actions">
              <span class="work-count">{{ visibleTasks.filter(t=>t.state==='in_progress').length }} 工作中</span>
              <div class="task-menu-anchor">
                <button class="task-control" :class="{active:issueFilterOpen}" @click="issueFilterOpen=!issueFilterOpen;issueDisplayOpen=false;issueViewOpen=false"><SlidersHorizontal :size="15"/>筛选</button>
                <div v-if="issueFilterOpen" class="task-popover filter-popover">
                  <div class="popover-heading"><strong>筛选任务</strong><button class="popover-close" @click="issueFilterOpen=false"><X :size="15"/></button></div>
                  <div class="filter-block"><small>状态</small><label v-for="state in [{key:'planned',label:'待规划'},{key:'todo',label:'待办'},{key:'in_progress',label:'进行中'},{key:'review',label:'审核中'},{key:'completed',label:'已完成'},{key:'blocked',label:'已阻塞'}]" :key="state.key"><input v-model="selectedStates" type="checkbox" :value="state.key"/> <span>{{ state.label }}</span></label></div>
                  <div class="filter-block"><small>优先级</small><label v-for="priority in [{key:'high',label:'高'},{key:'medium',label:'普通'},{key:'low',label:'低'}]" :key="priority.key"><input v-model="selectedPriorities" type="checkbox" :value="priority.key"/> <span>{{ priority.label }}</span></label></div>
                  <div class="popover-actions"><button class="text-action" @click="resetIssueFilters">重置</button><button class="solid-action" @click="applyIssueFilters">应用筛选</button></div>
                </div>
              </div>
              <div class="task-menu-anchor">
                <button class="task-control" :class="{active:issueDisplayOpen}" @click="issueDisplayOpen=!issueDisplayOpen;issueFilterOpen=false;issueViewOpen=false"><ArrowDownUp :size="15"/>手动</button>
                <div v-if="issueDisplayOpen" class="task-popover display-popover">
                  <div class="popover-heading"><strong>显示方式</strong><button class="popover-close" @click="issueDisplayOpen=false"><X :size="15"/></button></div>
                  <div class="popover-label">分组</div><div class="segmented"><button :class="{selected:issueGroup==='status'}" @click="issueGroup='status'">状态</button><button :class="{selected:issueGroup==='assignee'}" @click="issueGroup='assignee'">负责人</button></div>
                  <div class="popover-label">排序</div><button v-for="sort in [{key:'manual',label:'手动'},{key:'priority',label:'优先级'},{key:'title',label:'标题'},{key:'created',label:'创建时间'}]" :key="sort.key" class="select-row" :class="{selected:issueSort===sort.key}" @click="issueSort=sort.key"><span>{{ sort.label }}</span><CheckCircle2 v-if="issueSort===sort.key" :size="15"/></button>
                  <div class="popover-label">卡片字段</div><label class="switch-row"><input v-model="cardProperties.priority" type="checkbox"/>优先级</label><label class="switch-row"><input v-model="cardProperties.assignee" type="checkbox"/>负责人</label><label class="switch-row"><input v-model="cardProperties.dueDate" type="checkbox"/>截止日期</label>
                </div>
              </div>
              <div class="task-menu-anchor">
                <button class="task-control" :class="{active:issueViewOpen}" @click="issueViewOpen=!issueViewOpen;issueFilterOpen=false;issueDisplayOpen=false"><Kanban :size="15"/>看板</button>
                <div v-if="issueViewOpen" class="task-popover view-popover"><button :class="{selected:issueView==='board'}" @click="setIssueView('board')"><Kanban :size="16"/>看板<CheckCircle2 v-if="issueView==='board'" :size="15"/></button><button :class="{selected:issueView==='list'}" @click="setIssueView('list')"><List :size="16"/>列表<CheckCircle2 v-if="issueView==='list'" :size="15"/></button><button @click="notify('泳道视图将在负责人分组后显示')"><LayoutList :size="16"/>泳道</button></div>
              </div>
            </div>
          </div>
          <div class="issue-quick-tray" aria-label="任务快捷操作"><button aria-label="快捷菜单" @click="notify('快捷菜单已打开')"><Grip :size="18"/></button><button aria-label="搜索任务" @click="openQuickSearch"><Search :size="20"/></button><button class="quick-primary" aria-label="新建任务" @click="addTaskInLane()"><Plus :size="23"/></button><button aria-label="收件箱" @click="navigate('inbox')"><Inbox :size="19"/></button></div>
          <div v-if="loading" class="empty-wrap"><ZiEmptyState icon="◌" title="正在加载" description="正在读取工作区任务"/></div>
          <div v-else-if="issueView==='board'" class="task-board faithful-board">
            <section v-for="lane in lanes" :key="lane.key" class="task-lane" :data-state="lane.key">
              <header class="task-lane-header"><div class="lane-heading"><CircleDashed v-if="lane.key==='planned'" :size="16"/><Circle v-else-if="lane.key==='todo'" :size="16"/><CircleDot v-else-if="lane.key==='in_progress'" :size="16"/><CheckCircle2 v-else-if="lane.key==='review'" :size="16"/><CheckCircle2 v-else-if="lane.key==='completed'" :size="16"/><CircleAlert v-else :size="16"/><strong>{{ lane.label }}</strong><span>{{ lane.tasks.length }}</span></div><div class="lane-actions"><button aria-label="更多操作" @click="notify(`${lane.label}列菜单已打开`)"><MoreHorizontal :size="17"/></button><button aria-label="添加任务" @click="addTaskInLane(lane.key)"><Plus :size="17"/></button></div></header>
              <div class="task-lane-body"><article v-for="task in lane.tasks" :key="task.id" class="task-card" tabindex="0" @dblclick="openTaskDetail(task)" @keydown.enter="openTaskDetail(task)"><div class="task-card-title"><button class="task-card-title-link" @click="openTaskDetail(task)"><strong>{{ task.title }}</strong></button><button aria-label="任务菜单" @click.stop="openTaskDetail(task)"><MoreHorizontal :size="15"/></button></div><p v-if="task.description">{{ task.description }}</p><div class="task-meta" v-if="cardProperties.priority"><span class="priority-chip" :data-priority="task.priority">{{ task.priority==='high'?'高优先级':task.priority==='low'?'低优先级':'普通' }}</span><select :value="task.state" aria-label="更改任务状态" @change="moveTask(task,$event.target.value)"><option value="planned">待规划</option><option value="todo">待办</option><option value="in_progress">进行中</option><option value="review">审核中</option><option value="completed">已完成</option><option value="blocked">已阻塞</option></select></div></article><div v-if="!lane.tasks.length" class="lane-empty">无任务</div></div>
            </section>
          </div>
          <div v-else-if="!visibleTasks.length" class="empty-wrap compact"><ZiEmptyState icon="⌕" title="还没有任务" description="创建一个任务，把下一步行动交给紫薇。" action="创建任务" @action="addTaskInLane()"/></div>
          <ZiCard v-else><div class="doc-row" v-for="task in visibleTasks" :key="task.id" @dblclick="openTaskDetail(task)" tabindex="0"><button class="task-card-title-link" @click="openTaskDetail(task)" style="font-size:20px">▣</button><div class="row-main"><strong>{{ task.title }}</strong><small>{{ task.description || '暂无描述' }}</small></div><ZiStatusTag :status="task.state==='completed'?'online':'neutral'" :label="task.state"/><select :value="task.state" @change="moveTask(task,$event.target.value)"><option value="planned">待规划</option><option value="todo">待办</option><option value="in_progress">进行中</option><option value="review">审核中</option><option value="completed">已完成</option><option value="blocked">已阻塞</option></select></div></ZiCard>
        </div>
        <div v-else-if="page==='automations'" class="automations-page">
          <div class="page-header"><div><span class="eyebrow">AUTOMATION</span><h1>自动化</h1><p>用时间表或 Webhook 让紫薇重复执行工作。</p></div><ZiButton @click="showAutomation=true"><Plus :size="16"/>新建自动化</ZiButton></div>
          <div v-if="!automations.length" class="empty-wrap"><ZiEmptyState icon="↻" title="还没有自动化" description="创建一个模板或空白自动化，让紫薇按计划执行任务。" action="新建自动化" @action="showAutomation=true"/></div>
          <div v-else class="grid-3 automation-grid"><ZiCard v-for="automation in automations" :key="automation.id" class="automation-card"><div class="card-heading"><h3>{{ automation.name }}</h3><ZiStatusTag :status="automation.status==='active'?'online':'neutral'" :label="automation.status==='active'?'运行中':'已暂停'" dot/></div><p>{{ automation.prompt || '暂无运行说明' }}</p><div class="automation-meta"><span>{{ automation.schedule || '手动运行' }}</span><span>{{ automation.next_run ? `下次 ${automation.next_run}` : '尚未运行' }}</span></div><div class="skill-footer"><button class="pill" @click="notify('自动化详情已打开')">查看详情</button><button class="pill" @click="notify('自动化操作菜单已打开')">•••</button></div></ZiCard></div>
        </div>
        <div v-else-if="page==='calendar'" class="calendar-page">
          <div class="calendar-page-header">
            <div class="calendar-title"><CalendarDays :size="19"/><h1>日历</h1></div>
            <div class="calendar-view-switch"><button :class="{active:calendarView==='month'}" @click="calendarView='month'">月</button><button :class="{active:calendarView==='week'}" @click="calendarView='week'">周</button><button :class="{active:calendarView==='day'}" @click="calendarView='day'">日</button></div>
          </div>
          <div class="calendar-layout">
            <aside class="calendar-settings-panel">
              <h2>日历设置</h2>
              <button class="calendar-setting-row" :aria-pressed="calendarShowTasks === true" @click="calendarShowTasks=!calendarShowTasks"><span>显示任务</span><span class="calendar-switch" :class="{on:calendarShowTasks === true}"><i/></span></button>
              <button class="calendar-setting-row" :aria-pressed="calendarHumanOnly === true" @click="calendarHumanOnly=!calendarHumanOnly"><span>仅显示人类任务</span><span class="calendar-switch" :class="{on:calendarHumanOnly === true}"><i/></span></button>
              <label class="calendar-field"><span>任务筛选</span><select v-model="calendarTaskFilter"><option value="all">all</option><option value="planned">待规划</option><option value="todo">待办</option><option value="in_progress">进行中</option><option value="review">审核中</option><option value="completed">已完成</option><option value="blocked">已阻塞</option></select></label>
              <div class="calendar-projects"><h3>项目显示</h3><label><input v-model="calendarProjectVisible" type="checkbox"/> <span>test-111</span></label></div>
            </aside>
            <section class="calendar-main">
              <div class="calendar-toolbar"><button class="calendar-nav-button" aria-label="上个月" @click="moveCalendarMonth(-1)"><ChevronLeft :size="17"/></button><strong>{{ calendarMonthLabel }}</strong><button class="calendar-nav-button" aria-label="下个月" @click="moveCalendarMonth(1)"><ChevronRight :size="17"/></button><button class="calendar-today" @click="calendarToday">今天</button></div>
              <div v-if="calendarView==='month'" class="month-calendar"><div v-for="weekday in ['周日','周一','周二','周三','周四','周五','周六']" :key="weekday" class="weekday">{{ weekday }}</div><div v-for="cell in calendarGrid" :key="cell.key" class="calendar-cell" :class="{outside:cell.outside,today:cell.today}"><div class="calendar-cell-head"><span class="calendar-day-number" :class="{today:cell.today}">{{ cell.date.getDate() }}</span><button class="calendar-cell-add" aria-label="创建活动" title="创建活动" @click.stop="openAgentComposer"><Plus :size="12"/></button></div><div v-for="event in calendarEventsFor(cell.key)" :key="event.id" class="calendar-event" :data-status="event.status">{{ event.name }}</div></div></div>
              <div v-else-if="calendarView==='week'" class="week-calendar"><div v-for="cell in calendarWeekDays" :key="cell.key" class="week-column"><header>{{ ['周日','周一','周二','周三','周四','周五','周六'][cell.date.getDay()] }}<strong>{{ cell.date.getDate() }}</strong></header><div class="week-events"><div v-for="event in calendarEventsFor(cell.key)" :key="event.id" class="calendar-event" :data-status="event.status">{{ event.name }}</div></div></div></div>
              <div v-else class="day-calendar"><div class="day-heading"><span>{{ calendarCursor.getFullYear() }}年{{ calendarCursor.getMonth()+1 }}月{{ calendarCursor.getDate() }}日</span><small>当天安排</small></div><div v-for="event in calendarEventsFor(localDateKey(calendarCursor))" :key="event.id" class="day-event"><CalendarClock :size="17"/><span>{{ event.name }}</span></div><div v-if="!calendarEventsFor(localDateKey(calendarCursor)).length" class="day-empty">当天暂无安排</div></div>
            </section>
          </div>
          <div class="calendar-quick-tray" aria-label="日历快捷操作"><button aria-label="快捷菜单" @click="notify('快捷菜单已打开')"><Grip :size="18"/></button><button aria-label="搜索日历" @click="openQuickSearch"><Search :size="20"/></button><button class="quick-primary" aria-label="新建任务" title="新建任务" @click="openAgentComposer"><Plus :size="20"/></button><button aria-label="收件箱" @click="navigate('inbox')"><Inbox :size="19"/></button></div>
          <button class="floating-assistant calendar-cut" @click="notify('快捷剪贴板')">✂</button><button class="floating-assistant calendar-spark" @click="notify('紫薇助手')">◒</button><button class="chat-fab" @click="notify('帮助助手已打开')">◯</button>
        </div>
        <div v-else-if="page==='docs'" class="docs-page">
          <header class="docs-page-header">
            <div class="docs-title"><Folder :size="19"/><h1>文档</h1></div>
            <div class="docs-actions">
              <button class="docs-action-icon" aria-label="刷新文档" title="刷新" @click="refreshDocs"><RefreshCw :size="17"/></button>
              <button class="docs-action-button" @click="openDocUpload"><Upload :size="16"/>上传</button>
              <button class="docs-action-button" @click="openGitSync('export')">导出 Git</button>
              <button class="docs-action-button" @click="openGitSync('import')">导入 Git</button>
              <button class="docs-action-button" @click="openDocForm('file')"><FileText :size="16"/>新建 Markdown</button>
              <button class="docs-action-button" @click="openDocForm('folder')"><FolderPlus :size="16"/>新建文件夹</button>
              <input ref="docUploadInput" class="docs-upload-input" type="file" @change="handleDocUpload"/>
            </div>
          </header>
          <div class="docs-search-row"><label class="docs-search"><Search :size="18"/><input v-model="docsSearch" placeholder="搜索文档..." aria-label="搜索文档"/></label></div>
          <div class="docs-quota"><div class="docs-quota-label"><HardDrive :size="16"/><span>已用 {{ docsUsedBytes }} B / 10.0 GiB</span></div><div class="docs-quota-track"><span :style="{width:`${docsUsedPercent}%`}"></span></div></div>
          <div class="docs-browser">
            <aside class="docs-tree" aria-label="文档目录">
              <button class="docs-tree-row" :class="{selected:docsPath === docsRootFolder.id}" @click="docsPath === docsRootFolder.id ? openDocsRoot() : openDocFolder(docsRootFolder)"><ChevronRight :size="14" :class="{'docs-tree-chevron-open':docsPath === docsRootFolder.id}"/><component :is="docsPath === docsRootFolder.id ? FolderOpen : Folder" :size="19"/><span>说明文档</span></button>
              <button v-for="folder in documents.filter(doc=>doc.type==='folder' && !doc.parent_id && doc.id !== docsRootFolder.id)" :key="folder.id" class="docs-tree-row docs-tree-row-extra" :class="{selected:docsPath === folder.id}" @click="openDocFolder(folder)"><ChevronRight :size="14"/><Folder :size="19"/><span>{{ folder.name }}</span></button>
            </aside>
            <section class="docs-files" aria-live="polite">
              <div v-if="docsEntries.length" class="docs-entry-grid">
                <div v-for="entry in docsEntries" :key="entry.id" class="docs-entry-wrap"><button class="docs-entry-card" :class="{folder:entry.type==='folder'}" @dblclick="entry.type==='folder' && openDocFolder(entry)" @click="entry.type==='folder' ? openDocFolder(entry) : notify(`已打开 ${entry.name}`)"><Folder v-if="entry.type==='folder'" :size="37" stroke-width="1.7"/><FileText v-else :size="34" stroke-width="1.7"/><span>{{ entry.name }}</span></button><a v-if="entry.type!=='folder'" class="docs-entry-download" :href="api.downloadDocument(entry.id)" :download="entry.name" target="_blank" rel="noopener">下载</a></div>
              </div>
              <div v-else class="docs-empty-state"><Folder :size="48" stroke-width="1.4"/><div class="docs-empty-copy"><h2>暂无文件</h2><p>上传文件或创建文件夹来管理项目文档。</p></div><div class="docs-empty-actions"><button class="docs-empty-primary" @click="openDocUpload"><Upload :size="16"/>上传</button><button class="docs-empty-secondary" @click="openDocForm('folder')"><FolderPlus :size="16"/>新建文件夹</button></div></div>
            </section>
          </div>
          <div class="docs-quick-tray" aria-label="文档快捷操作"><button aria-label="快捷菜单" @click="notify('快捷菜单已打开')"><Grip :size="18"/></button><button aria-label="搜索文档" @click="document.querySelector('.docs-search input')?.focus()"><Search :size="20"/></button><button class="quick-primary" aria-label="新建文档" title="新建文档" @click="openDocForm('file')"><Plus :size="20"/></button><button aria-label="收件箱" @click="navigate('inbox')"><Inbox :size="19"/></button></div>
          <button class="floating-assistant docs-cut" @click="notify('快捷剪贴板')">✂</button><button class="floating-assistant docs-spark" @click="notify('紫薇助手')">◒</button><button class="chat-fab" @click="notify('帮助助手已打开')">◯</button>
        </div>

        <div v-else-if="page==='runtimes'" class="team-page"><header class="team-header"><div class="team-title"><Server :size="18"/><h1>运行时</h1><span>{{ runtimes.length }}</span></div><div class="header-actions"><ZiButton variant="secondary" @click="load"><RefreshCw :size="15"/>刷新</ZiButton><ZiButton @click="openDeviceModal(false)"><Server :size="15"/>添加设备</ZiButton></div></header><div class="environment-card"><div class="environment-toolbar"><span>Agent 环境</span><span>{{ devices.length }} 台设备 · {{ runtimes.length }} 个运行时</span></div><div v-if="!runtimes.length" class="empty-wrap compact"><ZiEmptyState icon="▣" title="暂无运行时" description="启动 ziwei_user 后会在这里显示桥接器和 CLI 版本。"/></div><div v-for="runtime in runtimes" :key="runtime.id" class="runtime-tree-row"><span class="online-dot" :class="{offline:runtime.cli_status!=='available'}"></span><ZiAvatar :name="runtime.name" size="sm"/><div class="entity-main"><strong>{{ runtime.name }}</strong><small>{{ runtime.name }} (ziwei_user)</small></div><div class="entity-tags"><button>版本 {{ runtime.cli_version || '等待 ziwei_user 心跳' }}</button><button>启动头 {{ runtime.name==='Claude'?'claude (stream-json)':runtime.name==='Codex'?'codex app-server':runtime.name==='Gemini'?'gemini (stream-json)':'hermes acp' }}</button></div><ZiStatusTag :status="runtime.cli_status==='available'?'online':'neutral'" :label="runtime.cli_status==='available'?'可用':'离线'" dot/></div></div></div>
        <div v-else-if="page==='members'" class="team-page">
          <header class="team-header">
            <div class="team-title"><Network :size="18"/><h1>团队管理</h1><span>{{ members.length + runtimes.length }}</span></div>
            <div class="header-actions"><ZiButton variant="secondary" @click="notify('管理工位功能已预留')"><Monitor :size="15"/>管理工位</ZiButton><ZiButton variant="secondary" @click="openDeviceModal(false)"><Server :size="15"/>添加设备</ZiButton><ZiButton variant="secondary" @click="showInvite=true"><UserRound :size="15"/>邀请伙伴</ZiButton><ZiButton @click="openEmployeeModal"><Plus :size="15"/>添加数字员工</ZiButton></div>
          </header>
          <div class="team-quick-tray" aria-label="团队快捷操作"><button aria-label="移动快捷操作托盘" title="拖动可移动；方向键微调，Home 键恢复居中。" @click="notify('快捷菜单已打开')"><Grip :size="18"/></button><button aria-label="搜索团队" title="搜索团队" @click="openQuickSearch"><Search :size="20"/></button><button class="quick-primary" aria-label="新建任务" title="新建任务" @click="openEmployeeModal"><Plus :size="20"/></button><button aria-label="审批" title="审批" @click="navigate('inbox')"><Inbox :size="19"/></button></div>
          <div class="team-view-tabs"><button :class="{active:teamView==='org'}" @click="teamView='org'"><Network :size="14"/>组织架构图</button><button :class="{active:teamView==='tree'}" @click="teamView='tree'"><LayoutList :size="14"/>目录树</button></div>
          <div class="team-scroll">
            <section v-if="teamView==='org'" class="org-chart" aria-label="组织架构图">
              <div class="org-workspace-card"><Network :size="24"/><strong>test-111</strong><span>工作区</span></div>
              <div class="org-connector org-connector-main"></div>
              <div class="org-owner-card"><div class="org-avatar">4</div><div class="org-owner-name"><strong>45</strong><span>你</span></div><div class="org-owner-role"><Crown :size="14"/>Owner</div></div>
              <div class="org-connector org-connector-owner"></div>
              <button class="org-add-employee" @click="openEmployeeModal"><Plus :size="14"/>添加数字员工</button>
            </section>
            <section v-else class="directory-tree" aria-label="目录树">
              <div class="directory-card">
                <div class="directory-workspace"><div class="directory-icon"><Network :size="17"/></div><div><div class="directory-name"><strong>test-111</strong><span>工作区</span></div></div></div>
                <div class="directory-member-group">
                  <div class="directory-row directory-member-summary"><div class="directory-icon"><UserRound :size="17"/></div><div class="directory-row-copy"><strong>成员</strong><span>1 位真人伙伴，0 个数字员工</span></div></div>
                  <div class="directory-row directory-owner-row"><div class="directory-avatar">4</div><div class="directory-row-copy"><strong>45 <small>你</small></strong><span><Crown :size="13"/> Owner</span></div></div>
                </div>
                <div class="directory-agent-group">
                  <div class="directory-row directory-agent-heading"><div class="directory-icon"><Server :size="17"/></div><div class="directory-row-copy"><strong>Agent环境</strong><span>1台设备</span></div><strong class="directory-count">我的设备 {{ devices.length }}</strong></div>
                  <div v-for="device in devices" :key="device.id" class="directory-device"><button class="directory-device-toggle" aria-label="展开设备"><ChevronDown :size="14"/></button><span class="online-dot" :class="{offline:device.status!=='online'}"></span><Monitor :size="16"/><div><strong>{{ device.name }}</strong><span class="soft-tag">ziwei_user</span><small>daemon {{ device.id.slice(0,10) }}… · {{ device.status==='online'?'心跳正常':'等待心跳' }}</small></div><strong class="directory-count">{{ runtimes.length }}/{{ runtimes.length }}</strong></div>
                </div>
              </div>
            </section>
            <section v-if="teamView==='org'" class="team-environment-section">
              <div class="team-section-title"><div><Server :size="17"/><strong>Agent环境</strong><span>{{ devices.length }}台设备</span></div></div>
              <div class="environment-card">
                <div class="environment-toolbar"><div class="environment-toolbar-left"><span>设备清单</span><span><UserRound :size="14"/>我的设备 {{ devices.length }}</span></div><span class="environment-summary">⌁ 一键折叠　{{ devices.length }}台设备，{{ runtimes.length }}个Agent环境，{{ employees.length }}个数字员工</span></div>
                <div v-if="!devices.length" class="empty-wrap compact"><ZiEmptyState icon="▣" title="还没有设备" description="登记本机设备后，ziwei_user 会在这里显示心跳。" action="添加设备" @action="openDeviceModal(false)"/></div>
                <div v-for="device in devices" :key="device.id" class="device-tree">
                  <div class="device-row"><span class="tree-chevron">⌄</span><span class="online-dot" :class="{offline:device.status!=='online'}"></span><Monitor :size="18"/><div class="entity-main"><div><strong>{{ device.name }}</strong><span class="soft-tag">ziwei_user</span></div><small>bridge {{ device.bridge_name || 'ziwei_user' }} · {{ device.id.slice(0,10) }}… · {{ device.status==='online'?'心跳正常':'已离线' }}</small></div><div class="entity-tags"><button @click="copyTeamValue(`设备 ${device.name} · ${device.os}`)">设备 {{ device.name }} · {{ device.os }}</button><button @click="copyTeamValue(`${device.bridge_name || 'ziwei_user'} ${device.bridge_version || 'unknown'}`)">{{ device.bridge_name || 'ziwei_user' }} CLI {{ device.bridge_version || '版本未知' }}</button><button @click="copyTeamValue(device.id)">Daemon {{ device.id.slice(0,10) }}…</button><button>最后在线 {{ device.status==='online'?'刚刚':'—' }}</button><button>创建时间 2026/9/28</button></div><strong class="entity-count">{{ runtimes.length }}个Agent环境　{{ runtimes.length }}/{{ runtimes.length }}</strong></div>
                  <div v-for="runtime in runtimes" :key="runtime.id" class="runtime-tree-row"><span class="tree-branch"></span><span class="online-dot" :class="{offline:runtime.cli_status!=='available'}"></span><ZiAvatar :name="runtime.name" size="sm"/><div class="entity-main"><div><strong>{{ runtime.name }}</strong><ZiStatusTag :status="runtime.cli_status==='available'?'online':'neutral'" :label="runtime.cli_status==='available'?'可用':'离线（等待 ziwei_user 心跳）'" dot/></div><small>{{ runtime.name }} ({{ device.name }})</small></div><div class="entity-tags"><button>版本 {{ runtime.cli_version || '等待 ziwei_user 心跳' }}</button><button>启动头 {{ runtime.name==='Claude'?'claude (stream-json)':runtime.name==='Codex'?'codex app-server':runtime.name==='Gemini'?'gemini (stream-json)':'hermes acp' }}</button><button>类型 内置</button><button>可见范围 仅创建者可用</button><button>最后在线 {{ runtime.cli_status==='available'?'刚刚':'—' }}</button></div><span class="employee-count">暂无数字员工</span></div>
                </div>
              </div>
              <div class="team-bottom-actions"><ZiButton variant="secondary" @click="openDeviceModal(false)"><Server :size="15"/>添加设备</ZiButton><ZiButton variant="secondary" @click="showInvite=true"><UserRound :size="15"/>邀请伙伴</ZiButton></div>
            </section>
          </div>
          <button class="floating-assistant cut" @click="notify('快捷剪贴板')">✂</button><button class="floating-assistant spark" @click="notify('紫薇助手')">◒</button><button class="chat-fab" @click="notify('帮助助手已打开')">◯</button>
        </div>

        <div v-else-if="page==='skills'" class="skills-page"><div class="page-header"><div><h1>技能中心</h1><p>浏览平台能力，或维护当前工作区的团队技能。</p></div><div class="header-actions"><ZiButton variant="secondary" @click="openSkillCatalog">平台目录</ZiButton><ZiButton variant="secondary" @click="openSkillImport">导入 SKILL.md</ZiButton><ZiButton @click="openSkillForm">添加团队技能</ZiButton></div></div><div class="skill-scope-tabs" role="tablist"><button type="button" :class="{active:skillScope==='platform'}" @click="skillScope='platform';skillTab='all'">平台技能 <span>{{ skills.filter(skill => (skill.scope || skill.source || 'platform') === 'platform').length }}</span></button><button type="button" :class="{active:skillScope==='team'}" @click="skillScope='team';skillTab='all'">团队技能 <span>{{ skills.filter(skill => (skill.scope || skill.source) === 'team').length }}</span></button></div><div class="toolbar skill-toolbar"><div class="skill-category-tabs"><button type="button" :class="{active:skillTab==='all'}" @click="skillTab='all'">全部</button><button v-for="category in skillCategories" :key="category" type="button" :class="{active:skillTab===category}" @click="skillTab=category">{{ category }}</button></div><input v-model="search" class="search" placeholder="搜索技能名称、描述或标签"/></div><div v-if="!filteredSkills.length" class="empty-wrap compact"><ZiEmptyState icon="✦" :title="skillScope==='team' ? '还没有团队技能' : '没有匹配的技能'" :description="skillScope==='team' ? '添加一个团队技能，让成员可以重复使用。' : '尝试调整分类或搜索关键词。'" :action="skillScope==='team' ? '添加团队技能' : ''" @action="openSkillForm"/></div><div v-else class="grid-3 skill-grid"><ZiCard v-for="skill in filteredSkills" :key="skill.id" class="skill-card"><div class="skill-card-icon">{{ skill.icon || '✦' }}</div><div class="card-heading"><h3>{{ skill.name }}</h3><ZiStatusTag :status="skill.installed?'online':'neutral'" :label="skill.installed?'已安装':'可安装'" dot/></div><p>{{ skill.description }}</p><div class="skill-meta"><span class="tag">{{ skill.category }}</span><span v-if="skill.recommended" class="skill-recommended">推荐</span><span>{{ skill.install_count || 0 }} 次安装</span></div><div class="skill-footer"><span class="skill-author">{{ skill.author || '紫薇团队' }}</span><ZiButton size="sm" :variant="skill.installed?'secondary':'primary'" @click="toggleSkill(skill)">{{ skill.installed?'停用':'安装' }}</ZiButton></div></ZiCard></div></div>

        <div v-else-if="page==='settings'"><div class="page-header"><div><h1>工作区设置</h1><p>配置紫薇的基础信息、访问权限和自动化策略。</p></div><ZiButton @click="saveSettings">保存更改</ZiButton></div><div class="settings-layout"><div class="settings-menu"><button v-for="tab in [{key:'general',label:'基本信息'},{key:'security',label:'安全与访问'},{key:'automations',label:'自动化默认值'},{key:'billing',label:'用量与计费'}]" :key="tab.key" :class="{active:settingsTab===tab.key}" @click="settingsTab=tab.key">{{ tab.label }}</button></div><ZiCard><div v-if="settingsTab==='general'" class="form-stack"><div class="card-heading"><h3>基本信息</h3><ZiStatusTag status="online" label="工作区正常" dot/></div><ZiFormField label="工作区名称" for-id="workspace-name"><ZiInput id="workspace-name" v-model="workspaceName"/></ZiFormField><ZiFormField label="工作区标识" hint="用于 API 和 A2A 路由"><ZiInput model-value="test-111" readonly/></ZiFormField><ZiFormField label="默认时区"><ZiSelect v-model="workspaceTimezone" :options="[{label:'Asia/Shanghai',value:'Asia/Shanghai'},{label:'UTC',value:'UTC'}]"/></ZiFormField></div><div v-else-if="settingsTab==='security'" class="form-stack"><div class="card-heading"><h3>安全与访问</h3><ZiSwitch v-model="switchValue" label="启用本机 daemon 心跳"/></div><p class="modal-copy">访问密钥只在创建时显示一次。前端只展示脱敏后的值，真实凭据不写入日志。</p><div class="runtime-row"><span>默认工作区密钥</span><span class="row-end">zwi_•••••••••••• · active</span></div><div class="runtime-row"><span>A2A agent</span><span class="row-end">ziwei_user</span></div></div><div v-else class="empty-wrap compact"><ZiEmptyState icon="⚙" title="可配置项正在准备" description="这个设置页的协议已经预留，后续可接入更多策略。"/></div></ZiCard></div></div>

        <div v-else-if="page==='invite'"><div class="page-header"><div><h1>邀请加入紫薇</h1><p>把团队成员加入当前工作区。</p></div></div><div class="grid-2"><ZiCard><div class="form-stack"><h3>邀请成员</h3><ZiFormField label="成员邮箱" required><ZiInput v-model="inviteForm.email" type="email" placeholder="name@example.com"/></ZiFormField><ZiFormField label="角色"><ZiSelect v-model="inviteForm.role" :options="[{label:'成员',value:'member'},{label:'管理员',value:'admin'}]"/></ZiFormField><div class="form-actions"><ZiButton @click="invite">发送邀请</ZiButton></div></div></ZiCard><ZiCard><div class="card-heading"><h3>邀请链接</h3><ZiStatusTag :status="inviteLink?'online':'neutral'" :label="inviteLink?'已生成':'未生成'"/></div><p class="modal-copy">邀请链接会绑定当前工作区和角色，方便在团队内部快速加入。</p><div v-if="inviteLink" class="invite-link-box">{{ inviteLink }}</div><ZiButton variant="secondary" @click="createInviteLink">生成并复制链接</ZiButton></ZiCard></div><ZiCard v-if="invitations.length" style="margin-top:16px"><div class="card-heading"><h3>邀请记录</h3><button class="pill" @click="loadInvitations">刷新</button></div><div v-for="item in invitations" :key="item.id" class="runtime-row"><div class="row-main"><strong>{{ item.email || '链接邀请' }}</strong><small>{{ item.role }} · {{ item.status }} · {{ item.expires_at }}</small></div><button v-if="item.status==='pending'" class="pill" @click="revokeInvite(item)">撤销</button></div></ZiCard></div>

        <div v-else-if="page==='invite-accept'" class="invite-accept-page"><ZiCard><div v-if="inviteAcceptState==='ready'" class="form-stack"><span class="eyebrow">INVITATION</span><h1>加入紫薇工作区</h1><p class="modal-copy">你正在接受 {{ inviteInfo?.workspace || '当前工作区' }} 的邀请。</p><ZiFormField label="姓名" required><ZiInput v-model="inviteAcceptForm.name" placeholder="你的姓名"/></ZiFormField><ZiFormField label="邮箱" required><ZiInput v-model="inviteAcceptForm.email" type="email" placeholder="name@example.com"/></ZiFormField><div class="form-actions"><ZiButton @click="acceptInvite">接受邀请</ZiButton></div></div><div v-else-if="inviteAcceptState==='accepted'" class="empty-wrap compact"><ZiEmptyState icon="✓" title="已加入工作区" description="邀请已确认，你现在可以返回紫薇继续工作。"/></div><div v-else class="empty-wrap compact"><ZiEmptyState icon="!" title="邀请链接不可用" description="链接可能已过期、撤销或不存在。"/></div></ZiCard></div>

        <div v-else-if="page==='open'"><div class="page-header"><div><h1>开放平台</h1><p>面向开发者的 API、A2A 和 Webhook 能力。</p></div><ZiButton @click="openApiKeyModal">创建 API Key</ZiButton></div><div class="grid-3"><ZiCard><div class="card-heading"><h3>REST API</h3><ZiStatusTag status="online" label="可用" dot/></div><p class="modal-copy">工作区数据、任务、文档、技能和自动化的统一 HTTP 接口。</p><button class="pill" @click="copyTeamValue(location.origin + '/api')">复制接口地址 →</button></ZiCard><ZiCard><div class="card-heading"><h3>A2A v1</h3><ZiStatusTag status="online" label="已启用" dot/></div><p class="modal-copy">Agent Card、Task、Message、状态查询和本机 ziwei_user 心跳。</p><button class="pill" @click="copyTeamValue(agents[0]?.id || 'ziwei_user')">{{ agents[0]?.id || 'ziwei_user' }} ↗</button></ZiCard><ZiCard><div class="card-heading"><h3>Webhook</h3><ZiStatusTag status="neutral" label="规划中"/></div><p class="modal-copy">将任务状态和自动化事件推送到外部系统。</p><button class="pill" @click="notify('Webhook 接入仍在规划中')">加入候选</button></ZiCard></div><ZiCard style="margin-top:16px"><div class="card-heading"><div><h3>API Keys</h3><p class="modal-copy">密钥只在创建或轮换时显示一次，服务端只保存哈希。</p></div><button class="pill" @click="openApiKeyModal">管理密钥</button></div><div v-if="!apiKeys.length" class="empty-wrap compact"><ZiEmptyState icon="⌁" title="还没有 API Key" description="创建一个密钥连接紫薇 REST API 或 A2A。"/></div><div v-else v-for="key in apiKeys" :key="key.id" class="runtime-row"><div class="row-main"><strong>{{ key.name }}</strong><small>{{ key.prefix }}•••• · {{ key.role }} · {{ key.status }}</small></div><span class="row-end">{{ key.last_used_at ? `最近使用 ${key.last_used_at}` : '尚未使用' }}</span></div></ZiCard></div>

        <div v-else-if="page==='inbox'"><div class="page-header"><div><h1>收件箱</h1><p>来自工作区、运行时和自动化的通知。</p></div><ZiButton variant="secondary" @click="notify('已全部标记为已读')">全部已读</ZiButton></div><ZiCard><div class="empty-wrap compact"><ZiEmptyState icon="✉" eyebrow="INBOX" title="收件箱是空的" description="新的任务指派、运行时消息和自动化结果会出现在这里。"/></div></ZiCard></div>
      </section>
  </WorkspaceShell>

  <div v-if="showAgentComposer" class="agent-composer-backdrop" @click.self="closeAgentComposer">
    <section class="agent-composer" :class="{expanded:agentComposerExpanded}" role="dialog" aria-modal="true" aria-label="通过数字伙伴创建">
      <header class="agent-composer-header">
        <div class="agent-composer-breadcrumb"><span>test-111</span><ChevronRight :size="13"/><strong>通过数字伙伴创建</strong></div>
        <div class="agent-composer-header-actions"><button aria-label="展开" title="展开" @click="agentComposerExpanded=!agentComposerExpanded"><Maximize2 :size="16"/></button><button aria-label="关闭" title="关闭" @click="closeAgentComposer"><X :size="16"/></button></div>
      </header>
      <div class="agent-composer-creator"><button><span>创建者</span><span>选一个数字伙伴...</span></button></div>
      <div class="agent-composer-editor"><textarea v-model="agentComposerText" placeholder="告诉数字伙伴要做什么，例如：&quot;新建任务：让李明跟进 API 文档更新，让王芳跟进支付流程测试。请确认分工后直接执行。&quot;"></textarea><div class="agent-composer-voice"><button aria-label="开始语音输入" title="开始语音输入"><Mic :size="14"/></button></div></div>
      <footer class="agent-composer-footer"><button class="agent-composer-attach" aria-label="添加附件" title="添加附件" @click="notify('附件将在任务详情中添加')"><Paperclip :size="14"/></button><button class="agent-composer-create" :disabled="!agentComposerText.trim()" @click="createFromAgentComposer">创建</button></footer>
    </section>
  </div>

  <ZiModal v-if="showComingSoon" title="工作流" @close="showComingSoon=false"><div class="empty-wrap compact"><ZiEmptyState icon="⌁" title="敬请期待" description="工作流能力正在接入紫薇，任务、日历和自动化入口已经可以使用。"/></div></ZiModal>
  <ZiModal v-if="showSearch" title="搜索任务" @close="showSearch=false"><div class="search-modal-content"><ZiInput v-model="search" autofocus placeholder="输入关键词搜索任务、描述或快捷命令"/><div class="search-command"><span>快捷操作</span><button @click="showSearch=false;addTaskInLane()"><Plus :size="15"/>新建任务</button><button @click="showSearch=false;navigate('inbox')"><Inbox :size="15"/>打开收件箱</button></div></div></ZiModal>
  <ZiModal v-if="showTask" title="快速创建任务" wide @close="showTask=false"><div class="form-stack"><ZiFormField label="标题" required><ZiInput v-model="taskForm.title" placeholder="例如：整理本周运营数据"/></ZiFormField><ZiFormField label="描述"><ZiTextarea v-model="taskForm.description" placeholder="补充任务背景、验收标准或上下文"/></ZiFormField><ZiFormField label="状态"><ZiSelect v-model="taskForm.state" :options="[{label:'待规划',value:'planned'},{label:'待办',value:'todo'},{label:'进行中',value:'in_progress'},{label:'审核中',value:'review'},{label:'已完成',value:'completed'},{label:'已阻塞',value:'blocked'}]"/></ZiFormField><ZiFormField label="优先级"><ZiSelect v-model="taskForm.priority" :options="[{label:'普通',value:'medium'},{label:'高',value:'high'},{label:'低',value:'low'}]"/></ZiFormField><ZiFormField label="截止日期"><ZiInput v-model="taskForm.dueDate" type="date"/></ZiFormField><div class="form-actions"><ZiButton variant="secondary" @click="showTask=false">取消</ZiButton><ZiButton @click="createTask">创建任务</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showTaskDetail" title="任务详情" wide @close="closeTaskDetail"><div v-if="taskDetail" class="task-detail-modal"><div class="task-detail-header"><div><span class="eyebrow">TASK</span><h2>{{ taskDetailForm.title }}</h2></div><ZiStatusTag :status="taskDetailForm.state==='completed'?'online':'neutral'" :label="taskDetailForm.state"/></div><div class="task-detail-grid"><section class="task-detail-main"><ZiFormField label="标题" required><ZiInput v-model="taskDetailForm.title"/></ZiFormField><div class="task-detail-editor"><label>描述</label><div class="task-editor-toolbar"><button type="button" @click="insertTaskSyntax('**','**')"><b>B</b></button><button type="button" @click="insertTaskSyntax('`','`')">代码</button><button type="button" @click="insertTaskSyntax('- ','')">列表</button><select v-model="taskDetailForm.descriptionFormat" aria-label="描述格式"><option value="plain">纯文本</option><option value="markdown">Markdown</option><option value="html">HTML</option></select></div><textarea v-model="taskDetailForm.description" class="task-detail-description" rows="9" placeholder="补充任务背景、验收标准或上下文"></textarea></div><div class="task-detail-fields"><ZiFormField label="状态"><ZiSelect v-model="taskDetailForm.state" :options="[{label:'待规划',value:'planned'},{label:'待办',value:'todo'},{label:'进行中',value:'in_progress'},{label:'审核中',value:'review'},{label:'已完成',value:'completed'},{label:'已阻塞',value:'blocked'}]"/></ZiFormField><ZiFormField label="优先级"><ZiSelect v-model="taskDetailForm.priority" :options="[{label:'普通',value:'medium'},{label:'高',value:'high'},{label:'低',value:'low'}]"/></ZiFormField><ZiFormField label="截止日期"><ZiInput v-model="taskDetailForm.dueDate" type="date"/></ZiFormField><ZiFormField label="负责人"><ZiInput v-model="taskDetailForm.assignee" placeholder="成员或数字员工"/></ZiFormField></div><div class="task-detail-actions"><ZiButton variant="secondary" @click="closeTaskDetail">取消</ZiButton><ZiButton @click="saveTaskDetail">保存修改</ZiButton></div></section><aside class="task-detail-side"><div class="task-detail-section"><div class="card-heading"><h3>附件</h3><button class="pill" type="button" @click="openTaskAttachmentPicker"><Paperclip :size="14"/>添加</button><input ref="taskAttachmentInput" type="file" hidden @change="handleTaskAttachmentUpload"/></div><div v-if="!taskAttachments.length" class="task-detail-empty">暂无附件</div><div v-for="attachment in taskAttachments" :key="attachment.id" class="task-attachment-row"><FileText :size="16"/><span class="row-main"><strong>{{ attachment.name }}</strong><small>{{ Math.ceil(Number(attachment.size||0)/1024) }} KB</small></span><button title="下载附件" @click="downloadTaskAttachment(attachment)"><Upload :size="14"/></button><button title="删除附件" @click="removeTaskAttachment(attachment)"><X :size="14"/></button></div></div><div class="task-detail-section"><h3>活动记录</h3><div v-if="!taskMessages.length" class="task-detail-empty">暂无消息</div><div v-for="message in taskMessages" :key="message.id" class="task-message"><small>{{ message.role }} · {{ message.created_at }}</small><p>{{ message.content }}</p></div><div class="task-message-compose"><textarea v-model="taskMessageDraft" rows="3" placeholder="添加一条更新..."></textarea><ZiButton size="sm" @click="sendTaskMessage">发送</ZiButton></div></div></aside></div></div></ZiModal>
  <ZiModal v-if="showSkillModal" title="添加团队技能" @close="showSkillModal=false"><div class="form-stack"><p class="modal-copy">团队技能只在当前工作区可见，可随时安装或停用。</p><ZiFormField label="名称" required><ZiInput v-model="skillForm.name" placeholder="例如：周报整理"/></ZiFormField><ZiFormField label="描述"><ZiTextarea v-model="skillForm.description" rows="4" placeholder="说明这个技能解决什么问题"/></ZiFormField><ZiFormField label="分类"><ZiSelect v-model="skillForm.category" :options="[{label:'自动化',value:'automation'},{label:'工程',value:'engineering'},{label:'生产力',value:'productivity'},{label:'研究',value:'research'},{label:'协调',value:'orchestration'}]"/></ZiFormField><ZiFormField label="标签"><ZiInput v-model="skillForm.tags" placeholder="用逗号分隔，例如：日报,团队"/></ZiFormField><div class="form-actions"><ZiButton variant="secondary" @click="showSkillModal=false">取消</ZiButton><ZiButton @click="createSkill">添加技能</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showSkillImport" title="导入 SKILL.md" wide @close="showSkillImport=false"><div class="form-stack"><p class="modal-copy">导入符合紫薇规范的 SKILL.md，系统会校验 frontmatter 并保存版本。</p><input ref="skillImportFile" type="file" accept=".md,.markdown,text/markdown" hidden @change="handleSkillImportFile"/><div class="form-actions"><ZiButton variant="secondary" @click="openSkillImportFile">选择 SKILL.md 文件</ZiButton></div><ZiFormField label="名称"><ZiInput v-model="skillImportForm.name" placeholder="可从 frontmatter 自动读取"/></ZiFormField><ZiFormField label="描述"><ZiInput v-model="skillImportForm.description" placeholder="可从 frontmatter 自动读取"/></ZiFormField><ZiFormField label="SKILL.md 内容" required><ZiTextarea v-model="skillImportForm.content" rows="12" placeholder="---\nname: my-skill\nversion: 1.0.0\n---\n\n# 用法"/></ZiFormField><div class="form-actions"><ZiButton variant="secondary" @click="showSkillImport=false">取消</ZiButton><ZiButton @click="importSkill">导入</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showDoc" title="新建项目文档" @close="showDoc=false"><div class="form-stack"><ZiFormField label="名称" required><ZiInput v-model="docForm.name" placeholder="README.md 或 资料文件夹"/></ZiFormField><ZiFormField label="类型"><ZiSelect v-model="docForm.type" :options="[{label:'Markdown 文件',value:'file'},{label:'文件夹',value:'folder'}]"/></ZiFormField><ZiFormField v-if="docForm.type==='file'" label="内容"><ZiTextarea v-model="docForm.content" rows="6" placeholder="# 项目笔记"/></ZiFormField><div class="form-actions"><ZiButton variant="secondary" @click="showDoc=false">取消</ZiButton><ZiButton @click="createDoc">保存</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showGitSync" :title="gitSyncMode==='export' ? '导出文档到 Git' : '从 Git 导入文档'" @close="showGitSync=false"><div class="form-stack"><p class="modal-copy">{{ gitSyncMode==='export' ? '将当前工作区文档导出到本机受控 Git 目录并提交。' : '读取本机受控 Git 目录中的文档并更新当前工作区。' }}</p><ZiFormField label="同步目录名" required><ZiInput v-model="gitSyncForm.name" placeholder="例如：test-111"/></ZiFormField><ZiFormField v-if="gitSyncMode==='export'" label="提交说明"><ZiInput v-model="gitSyncForm.message" placeholder="本次文档同步"/></ZiFormField><div class="form-actions"><ZiButton variant="secondary" @click="showGitSync=false">取消</ZiButton><ZiButton @click="runGitSync">{{ gitSyncMode==='export' ? '导出并提交' : '导入文档' }}</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showApiKeys" title="管理 API Key" wide @close="showApiKeys=false"><div class="form-stack"><p class="modal-copy">创建、轮换或撤销访问紫薇 REST API 的密钥。真实密钥只在创建和轮换后显示一次。</p><div v-if="createdApiToken" class="api-token-box"><strong>请立即复制新密钥</strong><code>{{ createdApiToken }}</code><ZiButton size="sm" @click="copyApiToken">复制密钥</ZiButton></div><ZiFormField label="名称" required><ZiInput v-model="apiKeyForm.name" placeholder="例如：本机 CLI"/></ZiFormField><ZiFormField label="角色"><ZiSelect v-model="apiKeyForm.role" :options="[{label:'成员',value:'member'},{label:'管理员',value:'admin'},{label:'所有者',value:'owner'}]"/></ZiFormField><ZiFormField label="过期时间"><ZiInput v-model="apiKeyForm.expiresAt" type="date"/></ZiFormField><div class="form-actions"><ZiButton @click="createApiKey">创建密钥</ZiButton></div><div class="api-key-list"><div v-for="key in apiKeys" :key="key.id" class="runtime-row"><div class="row-main"><strong>{{ key.name }}</strong><small>{{ key.prefix }}•••• · {{ key.role }} · {{ key.status }}</small></div><div class="api-key-actions"><button class="pill" :disabled="key.status!=='active'" @click="rotateApiKey(key)">轮换</button><button class="pill" :disabled="key.status!=='active'" @click="revokeApiKey(key)">撤销</button></div></div><p v-if="!apiKeys.length" class="task-detail-empty">暂无密钥</p></div></div></ZiModal>
  <ZiModal v-if="showInvite" title="邀请成员" @close="showInvite=false"><div class="form-stack"><ZiFormField label="邮箱"><ZiInput v-model="inviteForm.email" type="email" placeholder="name@example.com"/></ZiFormField><ZiFormField label="角色"><ZiSelect v-model="inviteForm.role" :options="[{label:'成员',value:'member'},{label:'管理员',value:'admin'}]"/></ZiFormField><div class="form-actions"><ZiButton @click="invite">发送邀请</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showDevice" :title="deviceSetupMode ? '连接本机 ziwei_user' : '添加本机设备'" wide @close="closeDeviceModal"><div class="device-install-modal"><p class="modal-copy">{{ deviceSetupMode ? '首次使用需要在这台电脑安装并启动紫薇 ziwei_user。它会通过心跳连接当前工作区，页面只认自己的 ziwei_user 状态。' : '先在这台电脑安装并启动紫薇 ziwei_user，它会主动连接当前工作区。紫薇不依赖 AuraBaba daemon，也不要求公网入站端口。' }}</p><div class="device-install-tabs" role="tablist"><button v-for="tab in [{key:'windows',label:'Windows'},{key:'macos',label:'macOS'},{key:'linux',label:'Linux'}]" :key="tab.key" type="button" :class="{active:deviceInstallTab===tab.key}" @click="deviceInstallTab=tab.key">{{ tab.label }}</button></div><div class="device-install-command"><div class="device-install-command-head"><strong>安装并连接 ziwei_user</strong><button type="button" class="pill" @click="copyDeviceCommand">{{ copiedDeviceCommand===deviceInstallTab?'已复制':'复制命令' }}</button></div><pre>{{ deviceInstallCommands[deviceInstallTab] }}</pre><small>命令只配置并启动本地 ziwei_user，不包含访问令牌。启动后可用 <code>npm run ziwei:status</code> 检查。</small></div><div class="device-install-status"><span class="online-dot" :class="{offline:!ownDeviceOnline}"></span><div><strong>{{ ownDeviceOnline?'ziwei_user 已在线':'等待 ziwei_user 上线' }}</strong><small>{{ ownDeviceOnline?`最近心跳 ${summary.device?.heartbeat_age_ms || 0}ms 前`:'安装并启动后点击刷新，页面会重新读取真实心跳。' }}</small></div><button type="button" class="pill" @click="load">刷新状态</button></div><div class="form-stack" v-if="!deviceSetupMode"><ZiFormField label="设备显示名称"><ZiInput v-model="deviceForm.name"/></ZiFormField><div class="form-actions"><ZiButton variant="secondary" @click="closeDeviceModal">关闭</ZiButton><ZiButton @click="addDevice">登记其他设备</ZiButton></div></div><div class="form-actions" v-else><ZiButton variant="secondary" @click="dismissDeviceSetup">稍后</ZiButton><ZiButton :disabled="!ownDeviceOnline" @click="closeDeviceModal">已连接，继续使用</ZiButton></div></div></ZiModal>
  <ZiModal v-if="showEmployee" title="创建数字伙伴" wide @close="showEmployee=false">
    <div class="employee-create-modal">
      <header class="employee-create-modal__header">
        <div><h2>创建数字伙伴</h2><p>为工作区创建一个新的 AI 数字伙伴。</p></div>
        <button type="button" class="employee-create-close" aria-label="关闭" @click="showEmployee=false"><X :size="18"/></button>
      </header>
      <nav class="employee-create-tabs" aria-label="创建方式">
        <button type="button" :class="{active:employeeModalTab==='manual'}" @click="employeeModalTab='manual'"><span>手动创建</span></button>
        <button type="button" :class="{active:employeeModalTab==='market'}" @click="employeeModalTab='market'"><FolderOpen :size="15"/><span>从伙伴市场创建</span></button>
      </nav>
      <div v-if="employeeModalTab==='market'" class="employee-market-empty">
        <div class="employee-market-icon">✦</div><h3>伙伴市场</h3><p>从工作区技能中心选择可复用的数字伙伴模板。</p>
        <button type="button" class="employee-secondary-button" @click="navigate('skills');showEmployee=false">浏览技能中心</button>
      </div>
      <div v-else class="employee-create-modal__body">
        <section class="employee-basic-grid">
          <div class="employee-avatar-picker"><div class="employee-avatar-placeholder">✦</div><button type="button" aria-label="移除头像" @click="notify('头像选择已预留')"><X :size="12"/></button></div>
          <div class="employee-field employee-field-name"><label for="employee-name">名称</label><input id="employee-name" v-model="employeeForm.name" autofocus placeholder="例如：深度研究数字伙伴" /></div>
          <div class="employee-field employee-field-description"><label for="employee-description">描述</label><input id="employee-description" v-model="employeeDescription" maxlength="255" placeholder="这个数字伙伴做什么？" /><span class="employee-counter">{{ employeeDescription.length }} / 255</span></div>
        </section>

        <section class="employee-field employee-visibility-field"><label>可见性</label><div class="employee-choice-grid">
          <button type="button" class="employee-choice-card" :class="{selected:employeeVisibility==='workspace'}" @click="employeeVisibility='workspace'"><span class="employee-choice-icon">◎</span><span><strong>工作区</strong><small>所有成员均可分配</small></span></button>
          <button type="button" class="employee-choice-card" :class="{selected:employeeVisibility==='personal'}" @click="employeeVisibility='personal'"><span class="employee-choice-icon">▣</span><span><strong>个人</strong><small>仅你和工作区管理员可分配</small></span></button>
        </div></section>

        <section class="employee-field"><label for="employee-runtime">运行工位 <span class="employee-info-mark">i</span></label><div class="employee-select-wrap"><button id="employee-runtime" type="button" class="employee-select-card" :aria-expanded="employeeRuntimeOpen" aria-haspopup="listbox" @click="employeeRuntimeOpen=!employeeRuntimeOpen;employeeModelOpen=false"><ZiAvatar :name="employeeForm.runtime" size="sm"/><div class="employee-select-copy"><strong>{{ runtimes.find(r=>r.name===employeeForm.runtime)?.name || employeeForm.runtime }} (ziwei_user)</strong><small>45</small></div><ChevronDown :size="17" :class="{open:employeeRuntimeOpen}"/></button><div v-if="employeeRuntimeOpen" class="employee-dropdown-menu" role="listbox" aria-label="运行工位"><button v-for="runtime in runtimes" :key="runtime.id" type="button" role="option" :aria-selected="employeeForm.runtime===runtime.name" :class="{selected:employeeForm.runtime===runtime.name}" @click="selectEmployeeRuntime(runtime.name)"><ZiAvatar :name="runtime.name" size="sm"/><span><strong>{{ runtime.name }} (ziwei_user)</strong><small>{{ runtime.cli_version || 'CLI 未检测到' }}</small></span><span v-if="employeeForm.runtime===runtime.name" class="employee-dropdown-check">✓</span></button><p v-if="!runtimes.length" class="employee-dropdown-empty">暂无可用运行工位</p></div></div></section>

        <section class="employee-field"><label for="employee-model">模型</label><div class="employee-select-wrap"><button id="employee-model" type="button" class="employee-select-card" :aria-expanded="employeeModelOpen" aria-haspopup="listbox" @click="employeeModelOpen=!employeeModelOpen;employeeRuntimeOpen=false;employeeModelSearch=''" ><span class="employee-card-icon">▣</span><div class="employee-select-copy"><strong>{{ selectedEmployeeModel ? `${selectedEmployeeModel.provider} · ${selectedEmployeeModel.label}` : '默认（提供方）' }}</strong><small>{{ selectedEmployeeModel?.id || '从运行工位提供方获取' }}</small></div><ChevronDown :size="17" :class="{open:employeeModelOpen}"/></button><div v-if="employeeModelOpen" class="employee-dropdown-menu employee-model-menu" role="listbox" aria-label="模型"><label class="employee-model-search"><Search :size="17"/><input v-model="employeeModelSearch" autofocus placeholder="搜索或输入模型 ID" aria-label="搜索或输入模型 ID" @click.stop /></label><div v-for="(entries, provider) in filteredEmployeeModels" :key="provider" class="employee-provider-group"><h4>{{ provider.toUpperCase() }}</h4><button v-for="model in entries" :key="model.id" type="button" role="option" :aria-selected="employeeModel===model.id" :class="{selected:employeeModel===model.id}" @click="selectEmployeeModel(model.id)"><span><strong>{{ model.provider }} · {{ model.label }}</strong><small>{{ model.id }}</small></span><span v-if="employeeModel===model.id" class="employee-dropdown-check">✓</span></button></div><p v-if="!Object.keys(filteredEmployeeModels).length" class="employee-dropdown-empty">没有匹配的模型</p></div></div></section>

        <section class="employee-field"><label for="employee-role">岗位说明</label><div class="employee-select-card employee-role-card"><FileText :size="17"/><input id="employee-role" v-model="employeeRole" placeholder="点击撰写岗位说明..."/><ChevronDown :size="17"/></div></section>

        <section class="employee-field employee-skills-field"><label>SKILLS</label><button type="button" class="employee-select-card employee-skills-select" @click="employeeSkillsOpen=!employeeSkillsOpen"><Plus :size="17"/><span>{{ employeeSkillIds.length ? `已选择 ${employeeSkillIds.length} 个 skill` : '从工作区添加 skill' }}</span><ChevronDown :size="17"/></button><div v-if="employeeSkillsOpen" class="employee-skills-list"><label v-for="skill in skills.slice(0,8)" :key="skill.id"><input type="checkbox" :checked="employeeSkillIds.includes(skill.id)" @change="toggleEmployeeSkill(skill.id)"/><span>{{ skill.name }}</span></label><p v-if="!skills.length">暂无可用 skill</p></div></section>
      </div>
      <footer class="employee-create-modal__footer"><button type="button" class="employee-cancel-button" @click="showEmployee=false">取消</button><button type="button" class="employee-create-button" :disabled="!employeeForm.name.trim()" @click="addEmployee">创建</button></footer>
    </div>
  </ZiModal>
  <ZiModal v-if="showAutomation" title="新建自动化" @close="showAutomation=false"><div class="form-stack"><ZiFormField label="名称" required><ZiInput v-model="automationForm.name" placeholder="例如：每日工作区摘要"/></ZiFormField><ZiFormField label="计划"><ZiInput v-model="automationForm.schedule"/></ZiFormField><ZiFormField label="指令"><ZiTextarea v-model="automationForm.prompt" rows="5" placeholder="让 agent 做什么？"/></ZiFormField><div class="form-actions"><ZiButton @click="createAutomation">保存自动化</ZiButton></div></div></ZiModal>
</template>
